import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {chapterHash} from '../lib/practice-chapters.ts';
import {collectionProgressId,roundProgressPrefix} from '../lib/round-progress.ts';
const root='docs/klink10-text-evidence-20261102',m=JSON.parse(readFileSync(root+'/manifest.json')),es=JSON.parse(readFileSync('public'+m.row.url)).exercises,base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:19041',out=process.env.KLINK_TEST_OUTPUT||root+'/local';mkdirSync(out+'/screens',{recursive:true});const checks=[],errors=[],key=roundProgressPrefix+collectionProgressId('text-evidence',m.row.id,m.row.url);
for(const[engine,type]of Object.entries({chromium,webkit})){
 const browser=await type.launch({headless:true,...(engine==='chromium'?{channel:'chrome'}:{})});
 try{for(const width of [390,1280]){const context=await browser.newContext({viewport:{width,height:844}});await context.addInitScript(()=>{window.allowEnd=false;window.Audio=class extends EventTarget{constructor(src){super();this.src=src;this.dataset={};this.currentTime=0;this.paused=true;this.playbackRate=1;}play(){this.paused=false;this.timer=setInterval(()=>{if(window.allowEnd){clearInterval(this.timer);this.paused=true;this.dispatchEvent(new Event('ended'));}},20);return Promise.resolve();}pause(){clearInterval(this.timer);this.paused=true;}};});const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(base);await page.evaluate(()=>localStorage.setItem('k10-existing-draft','Mijn bestaande antwoord'));await page.goto(base+'/'+chapterHash({chapter:'texts',activity:'text-evidence',collection:m.row.id,level:'a1',help:'practice'}));
 for(const[i,e]of es.entries()){const task=page.locator(`[data-exercise-id="${e.exerciseId}"]`);await task.waitFor();assert(await task.locator('[data-practice-next]').isDisabled());await page.evaluate(()=>{window.allowEnd=true;});await task.locator('.cp-instruction-listen').click();await task.locator('[data-word-token]').first().waitFor();await page.waitForFunction(id=>!document.querySelector(`[data-exercise-id="${id}"] [data-word-token]`).disabled,e.exerciseId);
 const ids=e.standardTask.acceptedSelections[0],wrong=e.standardTask.tokens.find(t=>!ids.includes(t.id)).id;await task.locator(`[data-word-token="${wrong}"]`).click();await task.locator('[data-practice-check]').click();assert(await task.locator('[data-practice-next]').isDisabled());await task.getByRole('button',{name:'Wis',exact:true}).click();
 for(const id of ids.slice(0,-1))await task.locator(`[data-word-token="${id}"]`).click();await task.locator('[data-practice-check]').click();assert(await task.locator('[data-practice-next]').isDisabled());await task.locator(`[data-word-token="${ids.at(-1)}"]`).click();await task.locator('[data-practice-check]').click();await task.locator('[data-practice-next]:not(:disabled)').waitFor();
 if(i===0)await page.screenshot({path:`${out}/screens/${engine}-${width}.png`,fullPage:true});await page.evaluate(()=>{window.allowEnd=false;});await task.locator('[data-practice-next]').click();await page.waitForFunction(({key,id})=>JSON.parse(localStorage.getItem(key)).done.includes(id),{key,id:e.exerciseId});if(i===0){await page.reload();await page.locator(`[data-exercise-id="${es[1].exerciseId}"]`).waitFor();}checks.push({engine,width,id:e.exerciseId,wrongAndIncompleteRejected:true,exactSentenceAccepted:true,manualAdvance:true});}
 assert.equal(await page.evaluate(()=>localStorage.getItem('k10-existing-draft')),'Mijn bestaande antwoord');assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)).done,key)).length,10);await context.close();}}finally{await browser.close();}}
assert.equal(checks.length,40);assert.deepEqual(errors,[]);writeFileSync(out+'/browser.json',JSON.stringify({base,checks,errors,completedProgressAndResumePreserved:true,existingDraftPreserved:true,audioMocked:true},null,2)+'\n');console.log('PASS 40 exact evidence-selection flows, progress, reload and existing draft.');
